/* A local, owner-scoped handoff shared by all project pages. No network requests. */
(()=>{'use strict';
const PREFIX='mediainfolab_lernprotokoll_v1:',SCHEMA='mediainfolab-lernprotokoll';
const names={werbespot:'Ein Werbespot',geschichte:'Eine Entscheidungsgeschichte',plakat:'Ein Plakat verbessern',app:'Eine eigene App entwerfen',tutorial:'Erklär’s besser',cockpit:'Mein digitales Cockpit',dokumente:'Alles in einer PDF',faktencheck:'Echt oder Fake?',lifehacks:'Fünf Tricks, die bleiben',nachrichten:'Würden Sie reagieren?',bildausschnitt:'Ein Bild. Zwei Eindrücke.',storyboard:'Eine Geschichte in sechs Bildern'};
const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function identity(){try{return String(JSON.parse(localStorage.getItem('mediainfolab_student_access_v1')||'{}').email||'').toLowerCase();}catch{return '';}}
let owner=identity(),records={},ok=true,active=null,dirty=false;
function clean(raw){const out={};if(!raw||typeof raw!=='object'||Array.isArray(raw))return out;for(const [key,v]of Object.entries(raw)){if(!/^(neu|kurz|alt):[a-z]+$/.test(key)||!v||typeof v!=='object')continue;const [group,id]=key.split(':');if(!names[id])continue;const rec={status:v.status==='fertig'?'fertig':'offen',done:String(v.done||'').slice(0,2000),file:String(v.file||'').slice(0,1000),next:String(v.next||'').slice(0,2000),updatedAt:typeof v.updatedAt==='string'&&!Number.isNaN(Date.parse(v.updatedAt))?v.updatedAt:'',history:[]};rec.history=(Array.isArray(v.history)?v.history:[]).slice(-12).map(h=>({date:String(h.date||'').slice(0,40),done:String(h.done||'').slice(0,2000),next:String(h.next||'').slice(0,2000),file:String(h.file||'').slice(0,1000),status:h.status==='fertig'?'fertig':'offen'}));out[key]=rec;}return out;}
function load(){owner=identity();try{records=clean(JSON.parse(localStorage.getItem(PREFIX+owner)||'{}'));ok=true;}catch{records={};ok=false;}}
function save(){try{if(!owner)throw Error();localStorage.setItem(PREFIX+owner,JSON.stringify(records));ok=true;}catch{ok=false;}return ok;}
function context(){const file=location.pathname.split('/').pop().replace(/\.html$/,'');const id=file==='projekt'?new URLSearchParams(location.search).get('thema'):location.hash.slice(1).split('/')[0];const group=file==='werkstatt45'?'neu':file==='projekt'?'kurz':file==='projekte'?'alt':'';return group&&names[id]?{key:group+':'+id,id,group,title:group==='kurz'&&id==='plakat'?'Was muss ich zuerst sehen?':names[id]}:null;}
function url(key){const [group,id]=key.split(':');return group==='neu'?'werkstatt45.html#'+id:group==='kurz'?'projekt.html?thema='+id+'&kurs=woche45':'projekte.html?kurs=woche45#'+id;}
function label(key){const [group,id]=key.split(':');return group==='kurz'&&id==='plakat'?'Was muss ich zuerst sehen?':names[id];}
function download(name,body,type){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([body],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),5000);}
function backup(){const good=save();download('Lernprotokoll-MedienInfoLab.json',JSON.stringify({schema:SCHEMA,version:1,owner,records},null,2),'application/json');return good;}
function readable(){const lines=['MEIN LERNPROTOKOLL · MEDIENINFOLAB',owner,'',...Object.entries(records).sort((a,b)=>b[1].updatedAt.localeCompare(a[1].updatedAt)).flatMap(([key,r])=>[label(key),r.updatedAt?'Stand: '+new Date(r.updatedAt).toLocaleString('de-CH'):'Entwurf','Status: '+(r.status==='fertig'?'Projekt fertig':'In Arbeit'),'Erledigt: '+r.done,'Datei: '+r.file,'Nächster Schritt: '+r.next,'Projekt: https://mediainfolab.com/'+url(key),''])];download('Mein-Lernprotokoll.txt','\ufeff'+lines.join('\n'),'text/plain;charset=utf-8');}
function renderOverview(){const container=document.querySelector('[data-journal-overview]');if(!container)return;const rows=Object.entries(records).filter(([,r])=>r.done||r.next||r.file).sort((a,b)=>b[1].updatedAt.localeCompare(a[1].updatedAt));const history=document.getElementById('journalHistory');if(history&&!history.dataset.initialised){history.open=rows.length>0;history.dataset.initialised='true';}container.innerHTML=rows.length?`<div class="lp-resumes">${rows.map(([key,r])=>`<article class="lp-resume"><span class="lp-label">${r.status==='fertig'?'Projekt fertig':'Hier geht es weiter'} ${r.updatedAt?'· '+e(new Date(r.updatedAt).toLocaleDateString('de-CH')):'· Entwurf'}</span><h3>${e(label(key))}</h3><p><b>Erledigt:</b> ${e(r.done)||'Noch nicht eingetragen'}</p><p><b>Nächster Schritt:</b> ${e(r.next)||'Noch nicht eingetragen'}</p><p><b>Datei / Ort:</b> ${e(r.file)||'Noch nicht eingetragen'}</p><a class="lp-btn" href="${url(key)}">Projekt öffnen →</a></article>`).join('')}</div>`:'<p>Sie haben noch kein Protokoll. Wählen Sie zuerst ein Projekt. Ihren Arbeitsstand halten Sie am Ende der Lektion fest.</p>';}
function refresh(){if(identity()!==owner)load();active=context();const button=document.getElementById('lpOpen');if(button){button.hidden=!active;button.textContent='Stopp & Protokoll';}renderOverview();}
function open(){active=context();if(!active)return;const r=records[active.key]||{done:'',file:'',next:'',status:'offen',history:[]};dirty=false;document.getElementById('lpTitle').textContent='Mein Schlussprotokoll · '+active.title;for(const k of ['done','file','next','status'])document.getElementById('lp-'+k).value=r[k];document.getElementById('lpFeedback').textContent=ok?'Entwürfe bleiben in diesem Browser. Sichern Sie am Ende zusätzlich die Datei.':'Browserspeicherung ist blockiert. Laden Sie die Sicherung herunter, bevor Sie die Seite schliessen.';document.getElementById('lpHistory').innerHTML=r.history.length?`<summary>Frühere Einträge dieses Projekts (${r.history.length})</summary>${[...r.history].reverse().map(h=>`<article><b>${e(h.date?new Date(h.date).toLocaleString('de-CH'):'Eintrag')} · ${h.status==='fertig'?'fertig':'in Arbeit'}</b><p>${e(h.done)}</p><p>Nächster Schritt: ${e(h.next)}</p><p>Datei: ${e(h.file)}</p></article>`).join('')}`:'';document.getElementById('lpDialog').showModal();document.getElementById('lp-done').focus();}
function draft(){if(!active)return;const old=records[active.key]||{history:[]};records[active.key]={...old,...Object.fromEntries(['done','file','next','status'].map(k=>[k,document.getElementById('lp-'+k).value])),updatedAt:new Date().toISOString()};dirty=true;save();document.getElementById('lpFeedback').textContent=ok?'Entwurf in diesem Browser gespeichert.':'Speichern im Browser nicht möglich. Laden Sie Ihre Sicherung herunter.';}
function commit(){draft();const r=records[active.key],missing=['done','file',...(r.status==='offen'?['next']:[])].find(k=>!r[k].trim());if(missing){document.getElementById('lpFeedback').textContent='Ergänzen Sie die leere Angabe. Beim nächsten Schritt genügt ein genauer Satz.';document.getElementById('lp-'+missing).focus();return false;}if(r.status==='fertig'&&!r.next.trim())r.next='Ein weiteres Projekt auswählen.';const last=r.history.at(-1);if(!last||['done','file','next','status'].some(k=>last[k]!==r[k]))r.history.push({date:r.updatedAt,done:r.done,file:r.file,next:r.next,status:r.status});r.history=r.history.slice(-12);save();dirty=false;renderOverview();document.getElementById('lpFeedback').textContent=ok?'Eintrag gespeichert. Laden Sie jetzt Ihre Protokoll-Sicherung herunter.':'Der Eintrag ist nur bis zum Schliessen verfügbar. Laden Sie jetzt die Sicherung herunter.';return true;}
function mount(){const wrap=document.createElement('div');wrap.id='lpRoot';wrap.innerHTML=`<button class="lp-floating" id="lpOpen" type="button" hidden>Stopp &amp; Protokoll</button><dialog class="lp-dialog" id="lpDialog" aria-labelledby="lpTitle"><form id="lpForm"><div class="lp-head"><h2 id="lpTitle">Mein Schlussprotokoll</h2><button class="lp-close" type="button" id="lpClose" aria-label="Protokoll schliessen">✕</button></div><p>Die letzten fünf Minuten: <b>Speichern Sie zuerst Ihre Ergebnisdatei</b>. Halten Sie danach Ihren Stand in kurzen Sätzen fest.</p><details class="lp-example"><summary>So sieht ein genauer Eintrag aus</summary><p><b>Erledigt:</b> App «Schon im Schrank», Ansichten 1–3 gestaltet.<br><b>Status:</b> In Arbeit.<br><b>Datei:</b> OneDrive → Informatik → Projekte → App Alex → App-Alex.pptx.<br><b>Nächster Schritt:</b> Auf Folie 3 den Button «Für morgen auswählen» mit Folie 4 verlinken.</p></details><label for="lp-done">Was haben Sie heute konkret erledigt?</label><textarea id="lp-done" maxlength="2000" rows="2" placeholder="Zum Beispiel: Folien 1–3 gestaltet und die Texte gekürzt."></textarea><label for="lp-status">Wo stehen Sie?</label><select id="lp-status"><option value="offen">In Arbeit – ich setze fort</option><option value="fertig">Projekt fertig und geprüft</option></select><label for="lp-file">Wie heisst Ihre Datei und wo liegt sie?</label><input id="lp-file" maxlength="1000" placeholder="OneDrive → Informatik → Projekte → … → Dateiname.pptx"><p class="lp-hint">Bei einem Browserprojekt: Name und Ordner Ihrer heruntergeladenen JSON-Sicherung. «In OneDrive» allein ist zu ungenau.</p><label for="lp-next">Was ist Ihr nächster Schritt?</label><textarea id="lp-next" maxlength="2000" rows="2" placeholder="Zum Beispiel: Auf Folie 3 den Button mit Folie 4 verlinken."></textarea><div class="lp-actions"><button class="lp-btn" type="submit">Eintrag speichern</button><button class="lp-btn secondary" type="button" id="lpDownload">Protokoll-Sicherung herunterladen</button><button class="lp-btn secondary" type="button" id="lpText">Lesbare Textdatei</button></div><p id="lpFeedback" role="status" aria-live="polite"></p><p class="lp-hint">Die Sicherung enthält alle Projektprotokolle. Verschieben Sie sie aus «Downloads» nach OneDrive → Informatik → Projekte. Auf einem anderen Gerät laden Sie sie auf Woche 45 über «Protokoll laden». Ihre PowerPoint, Videos und Projekt-Arbeitsstände sichern Sie zusätzlich.</p><details id="lpHistory"></details></form></dialog><input id="lpImport" type="file" accept=".json,application/json" hidden>`;document.body.append(wrap);
 document.getElementById('lpOpen').onclick=open;document.getElementById('lpClose').onclick=()=>{document.getElementById('lpDialog').close();renderOverview();};document.getElementById('lpForm').onsubmit=ev=>{ev.preventDefault();commit();};for(const k of ['done','file','next','status'])document.getElementById('lp-'+k).addEventListener('input',draft);document.getElementById('lpDownload').onclick=()=>{if(commit()){backup();document.getElementById('lpFeedback').textContent='Download gestartet. Öffnen Sie Downloads und verschieben Sie die JSON-Datei in Ihren Projektordner.';}};document.getElementById('lpText').onclick=()=>{if(commit())readable();};document.addEventListener('click',ev=>{const a=ev.target.closest('[data-journal-action]');if(!a)return;const action=a.dataset.journalAction;if(action==='import')document.getElementById('lpImport').click();if(action==='backup')backup();if(action==='text')readable();if(action==='open')open();});
 document.getElementById('lpImport').onchange=async ev=>{const f=ev.target.files?.[0];if(!f)return;const status=document.getElementById('lpImportStatus');try{if(f.size>500000)throw Error('Die Datei ist zu gross.');const raw=JSON.parse(await f.text());if(raw.schema!==SCHEMA||raw.version!==1)throw Error('Wählen Sie eine Lernprotokoll-Sicherung. Projekt-Arbeitsstände laden Sie im jeweiligen Projekt.');if(raw.owner!==owner)throw Error('Die Sicherung gehört zu einer anderen Schulmail.');if(!raw.records||typeof raw.records!=='object'||Array.isArray(raw.records))throw Error('Die Sicherung enthält keine lesbaren Einträge.');const incoming=clean(raw.records);if(!Object.keys(incoming).length)throw Error('Die Sicherung enthält noch keine ausgefüllten Protokolle.');if(!confirm('Diese Sicherung ersetzt die Protokolle zu den enthaltenen Projekten. Andere Projekte bleiben erhalten. Fortfahren?'))return;records={...records,...incoming};save();renderOverview();if(status)status.textContent=ok?'Protokolle geladen. Öffnen Sie Ihr Projekt über den Eintrag.':'Protokolle geladen, Browserspeicherung blockiert. Sichern Sie vor dem Schliessen erneut.';}catch(err){if(status)status.textContent=err.message||'Sicherung kann nicht gelesen werden.';else alert(err.message);}finally{ev.target.value='';}};
 load();refresh();}
window.MediaInfoJournal={refresh,open,backup,readable};document.addEventListener('project-render',refresh);window.addEventListener('hashchange',()=>setTimeout(refresh,0));window.addEventListener('storage',ev=>{if(ev.key==='mediainfolab_student_access_v1'){document.getElementById('lpDialog')?.close();load();refresh();}});document.addEventListener('submit',()=>setTimeout(refresh,0));
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount,{once:true});else mount();
})();
